#include <iostream>

// Ham tinh luy thua voi so mu mac dinh n = 2
double luythua(double x, int n = 2) {
    double kq = 1.0;
    for (int i = 0; i < n; ++i) {
        kq *= x;
    }
    return kq;
}

// Ham tinh tong voi tham so mac dinh o cuoi
int tong(int a, int b, int c = 0, int d = 0) {
    return a + b + c + d;
}

int main() {
    double base = 3.0;
    std::cout << luythua(base) << "\n";      // base^2 = 9
    std::cout << luythua(base, 3) << "\n";   // base^3 = 27
    std::cout << tong(10, 20) << "\n";       // 10 + 20 + 0 + 0 = 30
    std::cout << tong(10, 20, 5, 2) << "\n"; // 10 + 20 + 5 + 2 = 37
    return 0;
}

#include <iostream>

// Nap chong ham tim gia tri lon nhat cho int va double
int timMax(int a, int b) {
    return (a > b) ? a : b;
}

double timMax(double a, double b) {
    return (a > b) ? a : b;
}

// Nap chong ham tim gia tri lon nhat cho 3 so int
int timMax(int a, int b, int c) {
    return timMax(timMax(a, b), c);
}

int main() {
    // Goi cac phien ban nap chong
    std::cout << timMax(3, 5) << "\n";         // Goi timMax(int, int)
    std::cout << timMax(3.5, 2.1) << "\n";     // Goi timMax(double, double)
    std::cout << timMax(1, 9, 4) << "\n";       // Goi timMax(int, int, int)

    // Minh hoa bien tham chieu (reference alias)
    int x = 100;
    int& ref = x; // ref la bi danh cua x
    ref = 200;    // lam thay doi truc tiep gia tri cua x
    std::cout << x << " " << ref << "\n";

    return 0;
}
